assert.equal(cases.length,419);assert.deepEqual(cases.map(c=>c.id),expected.ids);assert.equal(new Set(expected.ids).size,419);
assert.equal(hash(JSON.stringify(expected.ids)),'27801c804733daa829c629af6acf41fdcfa44f441f42b05a995581b0a5fdeb8d');
